// Embedded Real Image Store for Vibe Together Cloud Deployment
const brandGraphic = "";
const pageBg = "";
const backBg = "";

const imageMap = {
  'hero.jpg': brandGraphic,
  'semibackground4.png': brandGraphic,
  'art.jpg': brandGraphic,
  'food.jpg': brandGraphic,
  'movie.png': brandGraphic,
  'music.jpg': brandGraphic,
  'sports.jpg': brandGraphic,
  'background.png': pageBg,
  'back.jpg': backBg
};

module.exports = {
  getImageBase64: function(name) {
    if (!name) return brandGraphic;
    const key = name.toLowerCase();
    if (imageMap[key]) return imageMap[key];
    if (key.includes('background') || key.includes('bg')) return pageBg;
    if (key.includes('back')) return backBg;
    return brandGraphic;
  },
  brandGraphic,
  pageBg,
  backBg
};
